#[derive(Debug, Clone, PartialEq)]
enum Shape { Circle(f64), Rect { w: u32, h: u32 }, Tri(u8, u8, u8), Empty }
fn classify(n: i64) -> &'static str {
    match n {
        i64::MIN..=-1 => "neg",
        0 => "zero",
        1 | 2 | 3 => "small",
        x if x % 2 == 0 => "even",
        4..=99 => "odd-mid",
        _ => "big",
    }
}
fn slice_pat(v: &[i32]) -> String {
    match v {
        [] => "empty".into(),
        [x] => format!("one {}", x),
        [first, .., last] if first == last => format!("same ends {}", first),
        [first, rest @ ..] => format!("first {} rest {:?}", first, rest),
    }
}
fn area(s: &Shape) -> u32 {
    match s {
        Shape::Circle(r) => (3.14 * r * r) as u32,
        Shape::Rect { w, h } => w * h,
        Shape::Tri(a, b, c) if a == b && b == c => 1,
        Shape::Tri(a, ..) => *a as u32,
        Shape::Empty => 0,
    }
}
fn parse_kv(s: &str) -> Option<(&str, i32)> {
    let Some((k, v)) = s.split_once('=') else { return None };
    let Ok(n) = v.trim().parse::<i32>() else { return None };
    Some((k.trim(), n))
}
